import json
import re
import sys


def invoke(args: dict) -> dict:
    """Estrae email valide da un testo, deduplicandole e ordinandole."""
    text = args.get("text", "")
    if not isinstance(text, str):
        return {"ok": False, "error": "'text' deve essere una stringa"}
    if not text.strip():
        return {"ok": False, "error": "'text' è vuoto o contiene solo spazi"}

    # Pattern RFC-semplificato: local@domain.tld
    # Evita lookbehind/lookahead; usa gruppi di cattura espliciti
    pattern = r"[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}"
    raw_matches = re.findall(pattern, text)

    # Normalizza in lowercase, deduplica, ordina
    unique_emails = sorted(set(m.lower() for m in raw_matches))

    content = "\n".join(unique_emails) if unique_emails else ""
    return {
        "ok": True,
        "content": content,
        "metadata": {
            "count": len(unique_emails),
            "emails": unique_emails,
        },
    }


def main() -> None:
    """Legge JSON da stdin, chiama invoke(), scrive JSON su stdout."""
    raw = sys.stdin.read()
    try:
        args = json.loads(raw)
    except json.JSONDecodeError as exc:
        result = {"ok": False, "error": f"JSON non valido: {exc}"}
    else:
        result = invoke(args)
    sys.stdout.write(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()
